/*  This example demonstrates Discounted Cash Flow (DCF) valuation using QuantLib.
    It shows how to:
    - Set up a yield term structure for discounting
    - Create a schedule of cash flows
    - Calculate present value and NPV
    - Model terminal value
    - Perform sensitivity analysis on discount rates
    - Calculate duration and convexity metrics
 */

#include <ql/qldefines.hpp>
#if !defined(BOOST_ALL_NO_LIB) && defined(BOOST_MSVC)
#  include <ql/auto_link.hpp>
#endif
#include <ql/termstructures/yield/flatforward.hpp>
#include <ql/cashflows/fixedratecoupon.hpp>
#include <ql/cashflows/cashflows.hpp>
#include <ql/time/schedule.hpp>
#include <ql/time/calendars/unitedstates.hpp>
#include <ql/time/daycounters/actualactual.hpp>
#include <ql/indexes/swap/euribor.hpp>
#include <iostream>
#include <iomanip>
#include <vector>
#include <cmath>

using namespace QuantLib;

class DCFAnalyzer {
public:
    DCFAnalyzer(const Date& evaluationDate, Rate discountRate)
        : evaluationDate_(evaluationDate), baseDiscountRate_(discountRate) {
        Settings::instance().evaluationDate() = evaluationDate_;
    }

    struct CashFlowAnalysis {
        Date date;
        Real amount;
        Real discountFactor;
        Real presentValue;
        Time yearFraction;
    };

    struct ValuationResults {
        Real npv;
        Real terminalValue;
        Real enterpriseValue;
        Real duration;
        Real convexity;
        std::vector<CashFlowAnalysis> cashFlows;
    };

    ValuationResults valuate(
        const std::vector<Date>& cashFlowDates,
        const std::vector<Real>& cashFlowAmounts,
        Real terminalValueAmount = 0.0,
        Rate discountRate = -1.0) {

        if (discountRate < 0.0) {
            discountRate = baseDiscountRate_;
        }

        // Build the yield curve using a flat forward rate
        Handle<YieldTermStructure> yieldCurve(
            ext::shared_ptr<YieldTermStructure>(
                new FlatForward(evaluationDate_, Handle<Quote>(), discountRate,
                                Actual365Fixed())));

        ValuationResults results;
        results.cashFlows.clear();
        results.npv = 0.0;
        results.terminalValue = terminalValueAmount;

        // Discount each cash flow
        DayCounter dayCounter = Actual365Fixed();
        Real duration = 0.0;
        Real convexity = 0.0;
        Real totalPresentValue = 0.0;

        for (size_t i = 0; i < cashFlowDates.size(); ++i) {
            Time t = dayCounter.yearFraction(evaluationDate_, cashFlowDates[i]);
            if (t < 0.0) continue; // Skip past dates

            Real df = yieldCurve->discount(cashFlowDates[i]);
            Real pv = cashFlowAmounts[i] * df;

            CashFlowAnalysis cf;
            cf.date = cashFlowDates[i];
            cf.amount = cashFlowAmounts[i];
            cf.discountFactor = df;
            cf.presentValue = pv;
            cf.yearFraction = t;

            results.cashFlows.push_back(cf);
            results.npv += pv;
            totalPresentValue += pv;

            // Duration calculation (Macaulay duration numerator)
            duration += t * pv;

            // Convexity calculation
            convexity += t * t * pv;
        }

        // Add terminal value
        if (terminalValueAmount > 0.0) {
            Time tFinal = dayCounter.yearFraction(
                evaluationDate_,
                cashFlowDates.back());
            Real dfFinal = yieldCurve->discount(cashFlowDates.back());
            results.npv += terminalValueAmount * dfFinal;
            totalPresentValue += terminalValueAmount * dfFinal;

            // Update duration and convexity for terminal value
            duration += tFinal * terminalValueAmount * dfFinal;
            convexity += tFinal * tFinal * terminalValueAmount * dfFinal;
        }

        results.enterpriseValue = results.npv;

        // Calculate modified duration and convexity (normalized by PV)
        if (totalPresentValue > 0.0) {
            results.duration = duration / totalPresentValue;
            results.convexity = (convexity / totalPresentValue) -
                               (results.duration * results.duration);
        }

        return results;
    }

    std::vector<ValuationResults> sensitivityAnalysis(
        const std::vector<Date>& cashFlowDates,
        const std::vector<Real>& cashFlowAmounts,
        Real terminalValueAmount,
        Real rateShiftBps) {

        std::vector<ValuationResults> results;

        // Calculate valuations at different rate levels
        Rate rateDown = baseDiscountRate_ - rateShiftBps / 10000.0;
        Rate rateBase = baseDiscountRate_;
        Rate rateUp = baseDiscountRate_ + rateShiftBps / 10000.0;

        results.push_back(valuate(cashFlowDates, cashFlowAmounts,
                                  terminalValueAmount, rateDown));
        results.push_back(valuate(cashFlowDates, cashFlowAmounts,
                                  terminalValueAmount, rateBase));
        results.push_back(valuate(cashFlowDates, cashFlowAmounts,
                                  terminalValueAmount, rateUp));

        return results;
    }

private:
    Date evaluationDate_;
    Rate baseDiscountRate_;
};

int main(int, char* []) {

    try {

        std::cout << std::endl
                  << "===== DISCOUNTED CASH FLOW (DCF) VALUATION EXAMPLE ====="
                  << std::endl << std::endl;

        /*****************************
         * SETUP AND MARKET DATA    *
         *****************************/

        Calendar calendar = UnitedStates();
        Date today(24, November, 2024);
        Settings::instance().evaluationDate() = today;

        std::cout << "Evaluation Date: " << today << std::endl;
        std::cout << std::string(60, '-') << std::endl << std::endl;

        // Create DCF analyzer with 5% discount rate
        Rate discountRate = 0.05;
        DCFAnalyzer analyzer(today, discountRate);

        std::cout << "Base Discount Rate: " << std::fixed << std::setprecision(2)
                  << (discountRate * 100.0) << "%" << std::endl << std::endl;

        /*****************************
         * SCENARIO 1: SIMPLE PROJECT *
         *****************************/

        std::cout << "SCENARIO 1: Simple 5-Year Project" << std::endl;
        std::cout << std::string(60, '-') << std::endl;

        std::vector<Date> projectDates;
        std::vector<Real> projectCashFlows;

        // Year 0: Initial investment (negative cash flow)
        projectDates.push_back(today);
        projectCashFlows.push_back(-1000.0);

        // Years 1-5: Operating cash flows
        for (int year = 1; year <= 5; ++year) {
            Date cfDate = calendar.advance(today, year, Years);
            projectDates.push_back(cfDate);
            projectCashFlows.push_back(300.0); // Annual operating cash flow
        }

        // Terminal value (salvage value at end of year 5)
        Real terminalValue = 100.0;

        DCFAnalyzer::ValuationResults projectResults =
            analyzer.valuate(projectDates, projectCashFlows, terminalValue);

        std::cout << "\nCash Flow Schedule:" << std::endl;
        std::cout << std::setw(12) << "Date"
                  << std::setw(15) << "Cash Flow"
                  << std::setw(15) << "Disc. Factor"
                  << std::setw(15) << "Present Value" << std::endl;
        std::cout << std::string(57, '-') << std::endl;

        for (const auto& cf : projectResults.cashFlows) {
            std::cout << std::setw(12) << cf.date
                      << std::setw(15) << std::fixed << std::setprecision(2)
                      << cf.amount
                      << std::setw(15) << std::fixed << std::setprecision(6)
                      << cf.discountFactor
                      << std::setw(15) << std::fixed << std::setprecision(2)
                      << cf.presentValue << std::endl;
        }

        std::cout << std::string(57, '-') << std::endl;
        std::cout << "Terminal Value (Year 5): " << std::fixed
                  << std::setprecision(2) << terminalValue << std::endl;
        std::cout << std::endl;

        std::cout << "Valuation Results:" << std::endl;
        std::cout << "  NPV (Net Present Value):    " << std::fixed
                  << std::setprecision(2) << projectResults.npv << std::endl;
        std::cout << "  Terminal Value (PV):        " << std::fixed
                  << std::setprecision(2) << (projectResults.npv -
            std::accumulate(projectResults.cashFlows.begin(),
                           projectResults.cashFlows.end(), 0.0,
                           [](Real sum, const DCFAnalyzer::CashFlowAnalysis& cf) {
                               return sum + cf.presentValue;
                           })) << std::endl;
        std::cout << "  Enterprise Value:           " << std::fixed
                  << std::setprecision(2) << projectResults.enterpriseValue
                  << std::endl;
        std::cout << "  Macaulay Duration (years):  " << std::fixed
                  << std::setprecision(4) << projectResults.duration << std::endl;
        std::cout << "  Convexity:                  " << std::fixed
                  << std::setprecision(6) << projectResults.convexity << std::endl;
        std::cout << std::endl;

        /*****************************
         * SCENARIO 2: BOND VALUATION *
         *****************************/

        std::cout << "SCENARIO 2: Corporate Bond Valuation" << std::endl;
        std::cout << std::string(60, '-') << std::endl;

        std::vector<Date> bondDates;
        std::vector<Real> bondCashFlows;

        Date bondIssueDate = today;
        Date bondMaturityDate = calendar.advance(today, 10, Years);
        Rate couponRate = 0.04; // 4% annual coupon
        Real faceValue = 1000.0;
        Real couponPayment = faceValue * couponRate;

        // Semi-annual coupon payments
        for (int i = 1; i <= 20; ++i) {
            Date paymentDate = calendar.advance(bondIssueDate, i * 6, Months);
            if (paymentDate <= bondMaturityDate) {
                bondDates.push_back(paymentDate);
                bondCashFlows.push_back(couponPayment / 2.0); // Semi-annual
            }
        }

        // Add face value at maturity
        bondDates.back();
        bondCashFlows.back() += faceValue;

        Real bondTerminalValue = 0.0; // No separate terminal value for bonds

        DCFAnalyzer::ValuationResults bondResults =
            analyzer.valuate(bondDates, bondCashFlows, bondTerminalValue);

        std::cout << "\nBond Details:" << std::endl;
        std::cout << "  Issue Date:        " << bondIssueDate << std::endl;
        std::cout << "  Maturity Date:     " << bondMaturityDate << std::endl;
        std::cout << "  Coupon Rate:       " << std::fixed << std::setprecision(2)
                  << (couponRate * 100.0) << "%" << std::endl;
        std::cout << "  Face Value:        " << std::fixed << std::setprecision(2)
                  << faceValue << std::endl << std::endl;

        std::cout << "Bond Valuation Results:" << std::endl;
        std::cout << "  Bond Price (NPV):           " << std::fixed
                  << std::setprecision(2) << bondResults.npv << std::endl;
        std::cout << "  Modified Duration (years):  " << std::fixed
                  << std::setprecision(4) << bondResults.duration << std::endl;
        std::cout << "  Convexity:                  " << std::fixed
                  << std::setprecision(6) << bondResults.convexity << std::endl;
        std::cout << std::endl;

        /*****************************
         * SENSITIVITY ANALYSIS      *
         *****************************/

        std::cout << "SCENARIO 3: Sensitivity Analysis - Rate Impact on NPV" << std::endl;
        std::cout << std::string(60, '-') << std::endl;

        Real rateShiftBps = 100.0; // 100 basis points
        std::vector<DCFAnalyzer::ValuationResults> sensitivityResults =
            analyzer.sensitivityAnalysis(projectDates, projectCashFlows,
                                        terminalValue, rateShiftBps);

        std::cout << "\nRate Scenario Analysis (Project Valuation):" << std::endl;
        std::cout << std::setw(20) << "Discount Rate"
                  << std::setw(20) << "NPV"
                  << std::setw(20) << "Change vs Base" << std::endl;
        std::cout << std::string(60, '-') << std::endl;

        Rate rates[] = {discountRate - rateShiftBps/10000.0,
                       discountRate,
                       discountRate + rateShiftBps/10000.0};
        std::string labels[] = {"Rate Down (-100bps)", "Base Rate",
                                "Rate Up (+100bps)"};

        for (size_t i = 0; i < 3; ++i) {
            Real change = sensitivityResults[i].npv - sensitivityResults[1].npv;
            std::cout << std::setw(20) << std::fixed << std::setprecision(2)
                      << (rates[i] * 100.0) << "%"
                      << std::setw(20) << std::fixed << std::setprecision(2)
                      << sensitivityResults[i].npv
                      << std::setw(20) << std::fixed << std::setprecision(2)
                      << change << std::endl;
        }

        std::cout << std::endl;

        // Calculate DV01 (dollar value of 1 basis point move)
        Real dv01 = (sensitivityResults[2].npv - sensitivityResults[0].npv) /
                    (2.0 * rateShiftBps);
        std::cout << "DV01 (sensitivity per 1 basis point):  " << std::fixed
                  << std::setprecision(4) << dv01 << std::endl;

        // Duration-based price change estimate
        Real estimatedDurationChange = -projectResults.duration * rateShiftBps / 10000.0 *
                                      sensitivityResults[1].npv;
        std::cout << "Est. Price Change (using duration):    " << std::fixed
                  << std::setprecision(2) << estimatedDurationChange << std::endl;
        std::cout << "Actual Price Change (rates up 100bps): " << std::fixed
                  << std::setprecision(2) << (sensitivityResults[2].npv -
                                               sensitivityResults[1].npv) << std::endl;

        std::cout << std::endl
                  << "===== END OF DCF VALUATION EXAMPLE =====" << std::endl
                  << std::endl;

        return 0;

    } catch (std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    } catch (...) {
        std::cerr << "Unknown error" << std::endl;
        return 1;
    }
}

